  eenheid:'hovenier', eenheidMv:'hoveniers', structuur:'de aangesloten hoveniers', hqPlaats:'de coöperatie', domein:'dutchqualitygardens.nl',
  heroH1:`Het merk trekt leads. Elke <span class="a">hovenier</span> wacht af welke.`,
